using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using BepInEx;
using BepInEx.Configuration;
using UnityEngine;
namespace LocalSpt5Esp;
internal sealed record CompanionPlan(string Id,string Name,SceneTemplate[] Members);
internal static class CompanionPlans {
 internal static ConfigEntry<bool> Automatic=null!;
 internal static ConfigEntry<float> SpawnDistance=null!,FollowDistance=null!,LootRadius=null!;
 internal static ConfigEntry<bool> LooseLoot=null!,Containers=null!,Corpses=null!,AutoDeliver=null!,AcceptOffers=null!;
 static ConfigEntry<string> activeId=null!;static bool loaded,corrupt;
 static readonly List<CompanionPlan> plans=new();static readonly List<SceneTemplate> members=new();
 static string name="我的编队",search="",count="1",group="普通 AI",notice="",selectedRole="assault",templateId="";static int difficulty=1;static bool customBirth;
 static Vector2 builderScroll,rosterScroll,templateScroll;static bool templates;
 static string FileName=>Path.Combine(BepInEx.Paths.PluginPath,"LocalSpt5ESP","companion-plans.json");
 internal static void Initialize(){const string section="51. 队友";Automatic=FeatureConfig.Bind(section,"Spawn squad on raid start","进入战局自动生成编队",false,"战前选好队友并开启；每场只自动提交一次，失败可在队友页补齐，不会无限补活阵亡队友。");activeId=FeatureConfig.Bind(section,"Active squad plan","当前编队 ID","");SpawnDistance=FeatureConfig.Bind(section,"Squad spawn distance","队友入场距离（米）",6f,"在玩家附近寻找同层、可达的原生 AI 生成位置。",new AcceptableValueRange<float>(1,25));FollowDistance=FeatureConfig.Bind(section,"Squad follow distance","队友跟随距离（米）",5f,"队伍会分散站位，避免全挤在玩家身边。",new AcceptableValueRange<float>(2,20));LootRadius=FeatureConfig.Bind(section,"Squad loot radius","搜物资范围（距玩家，米）",60f,"只搜索可达位置；战斗时优先自卫。",new AcceptableValueRange<float>(5,250));AcceptOffers=FeatureConfig.Bind(section,"Squad accept player drops","接收玩家丢下的物品",true,"跟随且未交战时，会捡起队友附近 8 米内玩家丢下的物品；保存在队友背包，按交付指令送回。");LooseLoot=FeatureConfig.Bind(section,"Squad loose loot","搜索地面物资",true);Containers=FeatureConfig.Bind(section,"Squad containers","搜索未上锁容器",true);Corpses=FeatureConfig.Bind(section,"Squad corpses","搜索尸体",true);AutoDeliver=FeatureConfig.Bind(section,"Squad auto deliver","有战利品后自动送回",true,"队友回到玩家身边，只丢本功能新捡到、可独立交付的物品，然后继续搜索。");Load();}
 static void Load(){if(loaded)return;loaded=true;try{plans.AddRange(PresetStorage.Load<CompanionPlan>(FileName));foreach(var p in plans)Validate(p.Members);var selected=plans.FirstOrDefault(p=>p.Id==activeId.Value)??plans.FirstOrDefault();if(selected!=null){activeId.Value=selected.Id;name=selected.Name;members.AddRange(selected.Members);}}catch(Exception e){corrupt=true;notice="编队存档读取失败，原文件保留："+e.Message;}}
 static void Validate(IEnumerable<SceneTemplate> rows){var list=rows.ToArray();CompanionRules.Validate(list.Select(r=>(r.Role,r.Side,r.Difficulty,r.Count)));if(list.Any(r=>string.IsNullOrWhiteSpace(r.Id)||r.Birth==null)||list.Select(r=>r.Id).Distinct().Count()!=list.Length)throw new ArgumentException("编队角色记录无效。");}
 internal static SceneTemplate[] Snapshot(){Load();if(corrupt)throw new ArgumentException(notice);Validate(members);return members.ToArray();}
 internal static int Total=>members.Sum(m=>m.Count);
 static void Save(){if(corrupt)throw new ArgumentException("原编队存档读取失败，未覆盖文件。");Validate(members);string id=activeId.Value;if(string.IsNullOrEmpty(id))activeId.Value=id=Guid.NewGuid().ToString("N");var value=new CompanionPlan(id,string.IsNullOrWhiteSpace(name)?"我的编队":name.Trim(),members.ToArray());int index=plans.FindIndex(p=>p.Id==id);if(index<0)plans.Add(value);else plans[index]=value;PresetStorage.Save(FileName,plans);notice="已保存编队“"+value.Name+"”，共 "+Total+" 名队友。";}
 static void Choose(CompanionPlan plan){activeId.Value=plan.Id;name=plan.Name;members.Clear();members.AddRange(plan.Members);notice="已载入编队。战局中的现有队友不会因此替换。";}
 static void Add(){var option=AiSpawnCatalog.Options.First(o=>o.Role==selectedRole);int amount=ItemSpawnRules.Integer(count,1,CompanionRules.Maximum,"队友数量");SceneTemplate entry;if(templates){var saved=SceneTemplates.Saved.FirstOrDefault(t=>t.Id==templateId)??throw new ArgumentException("先在下方选择 AI 模板。");entry=saved with{Id=Guid.NewGuid().ToString("N"),Count=amount};}else{var birth=customBirth?AiSpawnPresets.Snapshot():new AiBirthPreset(0,100,false,false,false,1,0,Array.Empty<string>(),EBodyPart.LeftLeg,60,1);entry=new(Guid.NewGuid().ToString("N"),option.Name,option.Role,option.Side,difficulty,amount,birth);}Validate(members.Append(entry));members.Add(entry);Save();}
 static void Action(Action action){try{action();}catch(Exception e){notice=e.Message;FeatureToasts.Show(notice);}}
 internal static void Draw(Rect rect,string page){Load();if(!CompanionSquad.SpawningEnabled){Automatic.Value=false;InterfaceMenu.Label(new Rect(rect.x,rect.y,rect.width,30),"队友生成已关闭",InterfaceMenu.Accent,19);InterfaceMenu.Paragraph(new Rect(rect.x,rect.y+45,rect.width,80),"已停用自动入场编队和手动补齐生成。已保存的编队保留；战局人数统计只计算其他角色。",null,13);return;}if(page=="队伍指令"){CompanionSquad.Draw(rect);return;}if(page=="物资与设置"){DrawSettings(rect);return;}
  float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w,28),"战前编队 · "+Total+" / 32 名",InterfaceMenu.Accent,19);y+=38;
  if(InterfaceMenu.Button(new Rect(x,y,w,36),Automatic.Value?"入场自动生成 · 已开启":"入场自动生成 · 未开启",Automatic.Value))Automatic.Value=!Automatic.Value;y+=46;
  float saveWidth=Math.Min(118,w*.22f);name=InterfaceMenu.Field(new Rect(x,y,w-saveWidth-10,30),name);if(InterfaceMenu.Button(new Rect(rect.xMax-saveWidth,y,saveWidth,30),"保存编队"))Action(Save);y+=40;
  var body=new Rect(x,y,w,Math.Max(120,rect.yMax-y-80));bool two=w>=780;float half=two?(w-16)/2:w;
  if(two){DrawBuilder(new Rect(x,y,half,body.height));DrawRoster(new Rect(x+half+16,y,half,body.height));}else{builderScroll=GUI.BeginScrollView(body,builderScroll,new Rect(0,0,w-22,1100));DrawBuilder(new Rect(0,0,w-24,580));DrawRoster(new Rect(0,596,w-24,490));GUI.EndScrollView();}
  InterfaceMenu.Paragraph(new Rect(x,rect.yMax-70,w,62),notice+"\n"+CompanionSquad.Summary,InterfaceMenu.Accent,12);
 }
 static void DrawBuilder(Rect rect){float x=rect.x,y=rect.y,w=rect.width;float half=(w-8)/2;if(InterfaceMenu.Button(new Rect(x,y,half,30),"选择类型",!templates))templates=false;if(InterfaceMenu.Button(new Rect(x+half+8,y,half,30),"使用 AI 模板",templates))templates=true;y+=40;
  if(!templates){var groups=AiSpawnCatalog.Groups;int columns=MenuWorkspaceLayout.Columns(w,100);float cell=(w-8*(columns-1))/columns;for(int i=0;i<groups.Length;i++)if(InterfaceMenu.Button(new Rect(x+i%columns*(cell+8),y+i/columns*36,cell,30),groups[i],group==groups[i])){group=groups[i];selectedRole=AiSpawnCatalog.Options.First(o=>o.Group==group).Role;}y+=MathF.Ceiling(groups.Length/(float)columns)*36+8;
   search=InterfaceMenu.Field(new Rect(x,y,w,30),search);y+=40;var options=AiSpawnCatalog.Options.Where(o=>o.Group==group&&(o.Name+" "+o.Role).Contains(search,StringComparison.OrdinalIgnoreCase)).ToArray();var area=new Rect(x,y,w,Math.Max(80,rect.yMax-y-145));templateScroll=GUI.BeginScrollView(area,templateScroll,new Rect(0,0,w-22,Math.Max(area.height-1,options.Length*40)));for(int i=0;i<options.Length;i++)if(InterfaceMenu.Button(new Rect(0,i*40,w-28,34),options[i].Name,selectedRole==options[i].Role))selectedRole=options[i].Role;GUI.EndScrollView();y=area.yMax+8;
   var difficulties=new[]{"简单","普通","困难","极难"};for(int i=0;i<4;i++)if(InterfaceMenu.Button(new Rect(x+i*w/4,y,w/4-5,28),difficulties[i],difficulty==i))difficulty=i;y+=36;
   if(InterfaceMenu.Button(new Rect(x,y,w,27),customBirth?"使用当前出生血量／装备设置 · 开":"使用原生血量与装备",customBirth))customBirth=!customBirth;y+=35;
  }else{var values=SceneTemplates.Saved;var area=new Rect(x,y,w,Math.Max(100,rect.yMax-y-68));templateScroll=GUI.BeginScrollView(area,templateScroll,new Rect(0,0,w-22,Math.Max(area.height-1,values.Length*44)));for(int i=0;i<values.Length;i++)if(InterfaceMenu.Button(new Rect(0,i*44,w-28,36),values[i].Name+" · "+values[i].Role,templateId==values[i].Id))templateId=values[i].Id;if(values.Length==0)InterfaceMenu.Paragraph(new Rect(4,8,w-34,70),"还没有保存的 AI 模板。可先在 AI 管理保存角色或出生设置，再回到本页使用。",null,12);GUI.EndScrollView();y=area.yMax+12;}
  count=InterfaceMenu.Field(new Rect(x,y,60,32),count);if(InterfaceMenu.Button(new Rect(x+70,y,w-70,32),"加入战前编队"))Action(Add);
 }
 static void DrawRoster(Rect rect){float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w,26),"已选队友 · 自动保存",InterfaceMenu.Accent,16);y+=34;var area=new Rect(x,y,w,Math.Max(80,rect.height-145));rosterScroll=GUI.BeginScrollView(area,rosterScroll,new Rect(0,0,w-22,Math.Max(area.height-1,members.Count*90)));for(int i=0;i<members.Count;i++){var entry=members[i];float top=i*90;InterfaceMenu.Surface(new Rect(0,top,w-28,82),Color.Lerp(InterfaceMenu.Background,InterfaceMenu.Accent,.04f),7);InterfaceMenu.Label(new Rect(10,top+4,w-48,26),entry.Name+" ×"+entry.Count,InterfaceMenu.Text,14);InterfaceMenu.Label(new Rect(10,top+36,w-130,25),entry.Role+" · "+new[]{"简单","普通","困难","极难"}[entry.Difficulty],null,11);if(InterfaceMenu.Button(new Rect(w-112,top+38,74,28),"移除")){Action(()=>{members.Remove(entry);Save();});break;}}if(members.Count==0)InterfaceMenu.Paragraph(new Rect(6,12,w-36,75),"先从左侧加入 Scav、PMC、BOSS 或黑色军团队友，再开启入场自动生成。",null,13);GUI.EndScrollView();y=area.yMax+8;
  var choices=plans.Where(p=>p.Id!=activeId.Value).TakeLast(4).ToArray();int cols=Math.Max(1,MenuWorkspaceLayout.Columns(w,135));for(int i=0;i<choices.Length;i++)if(InterfaceMenu.Button(new Rect(x+i%cols*(w/cols),y+i/cols*34,w/cols-6,28),"载入："+choices[i].Name))Choose(choices[i]);
  if(InterfaceMenu.Button(new Rect(x,rect.yMax-30,w,28),"另存为新编队"))Action(()=>{activeId.Value=Guid.NewGuid().ToString("N");Save();});
 }
 static void DrawSettings(Rect rect){var entries=new ConfigEntryBase[]{SpawnDistance,FollowDistance,LootRadius,AcceptOffers,LooseLoot,Containers,Corpses,AutoDeliver};builderScroll=GUI.BeginScrollView(rect,builderScroll,new Rect(0,0,rect.width-22,entries.Length*88+160));for(int i=0;i<entries.Length;i++)InterfaceMenu.DrawEntry(entries[i],new Rect(6,i*88,rect.width-40,80));InterfaceMenu.Paragraph(new Rect(8,entries.Length*88+8,rect.width-44,135),"搜索时队友会走到目标附近，使用原生 AI 拾取。交付时回到玩家身边再丢物资。保留入队时已有的装备、手持武器和穿戴物；已合并进原有堆叠的物资会保留。\n战前模板保留血量、装备与 Buff；编队入场会解除出生暂停、动作锁定和敌对设置，以便接收队伍指令。",null,12);GUI.EndScrollView();}
}
